IntegerKeyParam::IntegerKeyParam() : tag_(Tag::kBooleanValue) {
  data_.boolean_value = bool();
}

IntegerKeyParam::~IntegerKeyParam() {
  DestroyActive();
}


void IntegerKeyParam::set_boolean_value(
    bool boolean_value) {
  if (tag_ != Tag::kBooleanValue) {
    DestroyActive();
    tag_ = Tag::kBooleanValue;
  }
  data_.boolean_value = boolean_value;
}
void IntegerKeyParam::set_integer(
    uint32_t integer) {
  if (tag_ != Tag::kInteger) {
    DestroyActive();
    tag_ = Tag::kInteger;
  }
  data_.integer = integer;
}
void IntegerKeyParam::set_long_integer(
    uint64_t long_integer) {
  if (tag_ != Tag::kLongInteger) {
    DestroyActive();
    tag_ = Tag::kLongInteger;
  }
  data_.long_integer = long_integer;
}
void IntegerKeyParam::set_date_time(
    uint64_t date_time) {
  if (tag_ != Tag::kDateTime) {
    DestroyActive();
    tag_ = Tag::kDateTime;
  }
  data_.date_time = date_time;
}
void IntegerKeyParam::set_blob(
    std::vector<uint8_t> blob) {
  if (tag_ == Tag::kBlob) {
    *(data_.blob) = std::move(blob);
  } else {
    DestroyActive();
    tag_ = Tag::kBlob;
    data_.blob = new std::vector<uint8_t>(
        std::move(blob));
  }
}

void IntegerKeyParam::DestroyActive() {
  switch (tag_) {

    case Tag::kBooleanValue:

      break;
    case Tag::kInteger:

      break;
    case Tag::kLongInteger:

      break;
    case Tag::kDateTime:

      break;
    case Tag::kBlob:

      delete data_.blob;
      break;
  }
}

bool IntegerKeyParam::Validate(
    const void* data,
    mojo::internal::ValidationContext* validation_context) {
  return Data_::Validate(data, validation_context, false);
}
