// static
bool KeymasterHostStubDispatch::AcceptWithResponder(
    KeymasterHost* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kKeymasterHost_GetServer_Name: {

      internal::KeymasterHost_GetServer_Params_Data* params =
          reinterpret_cast<
              internal::KeymasterHost_GetServer_Params_Data*>(
                  message->mutable_payload());
      
      bool success = true;
      KeymasterHost_GetServer_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            KeymasterHost::Name_, 0, false);
        return false;
      }
      KeymasterHost::GetServerCallback callback =
          KeymasterHost_GetServer_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->GetServer(std::move(callback));
      return true;
    }
  }
  return false;
}


