// static
bool UnionTraits<::arc::mojom::IntegerKeyParam::DataView, ::arc::mojom::IntegerKeyParamPtr>::Read(
    ::arc::mojom::IntegerKeyParam::DataView input,
    ::arc::mojom::IntegerKeyParamPtr* output) {
  using UnionType = ::arc::mojom::IntegerKeyParam;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kBooleanValue: {
      *output = UnionType::NewBooleanValue(input.boolean_value());
      break;
    }
    case Tag::kInteger: {
      *output = UnionType::NewInteger(input.integer());
      break;
    }
    case Tag::kLongInteger: {
      *output = UnionType::NewLongInteger(input.long_integer());
      break;
    }
    case Tag::kDateTime: {
      *output = UnionType::NewDateTime(input.date_time());
      break;
    }
    case Tag::kBlob: {
      std::vector<uint8_t> result_blob;
      if (!input.ReadBlob(&result_blob))
        return false;

      *output = UnionType::NewBlob(
          std::move(result_blob));
      break;
    }
    default:

      return false;
  }
  return true;
}

